mapper.sql:
WITH objRec AS( SELECT tmp1.PROD_ID, tmp1.VDATE, NVL(tmp1.actEndMDate,tmp1.MDate) MDATE, TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd') as holdDate FROM ( SELECT A.PROD_ID, A.VDATE, A.MDATE, B.MDATE AS actEndMDate, B.STATUS, ROW_NUMBER() over( partition by A.PROD_ID ORDER BY B.UPDATE_TIME DESC) AS endStatusNo FROM CHB_PRD_BASEINFO A LEFT JOIN CHB_PRD_END_SUB B ON A.PROD_ID = B.PROD_ID WHERE A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
AND A.FPROD_ID is null AND TO_DATE(TO_CHAR(A.VDATE, 'yyyy-MM-dd'), 'yyyy-MM-dd') <= TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd') ) tmp1 WHERE endStatusNo = 1 AND NVL(tmp1.STATUS,'01') != '03' AND TO_DATE(TO_CHAR(NVL(actEndMDate,MDATE), 'yyyy-MM-dd'), 'yyyy-MM-dd') > TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd') )
